#!/usr/bin/env node
// discord-digest/post.mjs — deterministic write for the "discord-digest"
// Cadence, invoked by the CCR agent-runner AFTER it has *generated* the weekly
// digest prose. The LLM owns the judgment (which deliverables/posts/decisions
// matter this week, how to theme and voice them); this script owns the
// structurally-exact write to Discord so a malformed embed can't recur.
//
// Unlike feed-post (Bearer token → wf-agents-api) the Discord credential IS the
// destination: the injected discord.webhook_url is the URL we POST the embed to
// directly — no separate endpoint constant, no bearer header (Discord webhooks
// authenticate by the unguessable URL itself). Mirrors discord-heartbeat/post.mjs.
//
// Body is read from a FILE (not an arg) so multi-line / Unicode prose can't be
// mangled by shell quoting. The webhook URL is injected per-fire
// (credentials['discord.webhook_url'].url) — never read from anywhere else.
//
// Usage:
//   DISCORD_WEBHOOK_URL="<credentials['discord.webhook_url'].url>" \
//     node workforce/skills/discord-digest/post.mjs \
//       --agent priya --body-file /tmp/digest.md \
//       [--title "Weekly workforce digest · week of 2026-06-01"] [--skill-version 0.1.0]
//
// Exit codes:
//   0  — Discord returned 2xx (posted)
//   1  — bad args / env / body-file unreadable / body fails W-1
//   2  — non-2xx response from Discord (e.g. 400 malformed, 401 bad URL)
//   3  — network / fetch error

import { readFileSync } from "node:fs";

const COLOR_DIGEST = 0x9b59b6; // amethyst — distinct from heartbeat's info-blue
// Discord embed description hard cap. We fail loud rather than truncate (C-1).
const DISCORD_EMBED_DESC_MAX = 4096;

function arg(name) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : undefined;
}

const webhookUrl = process.env.DISCORD_WEBHOOK_URL;
const agent = arg("agent");
const bodyFile = arg("body-file");
const title = arg("title") ?? "Weekly workforce digest";
const skillVersion = arg("skill-version");

if (!webhookUrl) { console.error("post.mjs: DISCORD_WEBHOOK_URL env var is required (from credentials['discord.webhook_url'].url)"); process.exit(1); }
if (!/^https:\/\/discord\.com\/api\/webhooks\//.test(webhookUrl)) {
  console.error(`post.mjs: DISCORD_WEBHOOK_URL does not look like a Discord webhook URL (got "${webhookUrl.slice(0, 60)}...")`);
  process.exit(1);
}
if (!agent) { console.error("post.mjs: --agent <slug> is required"); process.exit(1); }
if (!bodyFile) { console.error("post.mjs: --body-file <path> is required"); process.exit(1); }

let body;
try {
  body = readFileSync(bodyFile, "utf8").trim();
} catch (err) {
  console.error(`post.mjs: cannot read --body-file "${bodyFile}": ${err instanceof Error ? err.message : String(err)}`);
  process.exit(1);
}

// W-1 editorial guard (client side). A degraded digest fails loud here rather
// than landing in the channel.
const ARTEFACTS = ["as an ai", "i apologize", "i'm sorry", "certainly!", "sure, ", "here is the", "here's the"];
const head = body.slice(0, 50).toLowerCase();
if (body.length === 0) { console.error("post.mjs: digest body is empty (W-1)"); process.exit(1); }
if (ARTEFACTS.some((a) => head.startsWith(a))) { console.error(`post.mjs: body opens with an LLM-failure artefact (W-1): "${head}"`); process.exit(1); }
if (body.length > DISCORD_EMBED_DESC_MAX) {
  console.error(`post.mjs: digest body is ${body.length} chars; Discord embed description hard cap is ${DISCORD_EMBED_DESC_MAX}. Shorten it (do not truncate — C-1) and re-run.`);
  process.exit(1);
}

const payload = {
  embeds: [
    {
      title: title.slice(0, 256), // Discord title cap
      description: body,
      color: COLOR_DIGEST,
      timestamp: new Date().toISOString().replace(/\.\d+Z$/, "Z"),
      footer: { text: `wf-digest · ${agent}${skillVersion ? ` · v${skillVersion}` : ""}` },
    },
  ],
};

try {
  const res = await fetch(webhookUrl, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(payload),
  });
  if (res.status < 200 || res.status >= 300) {
    const text = await res.text().catch(() => "");
    console.error(`post.mjs: Discord webhook returned HTTP ${res.status}: ${text.slice(0, 256)}`);
    process.exit(2);
  }
  console.log(`post.mjs: posted weekly digest for ${agent} (${body.length} chars)`);
  process.exit(0);
} catch (err) {
  console.error(`post.mjs: fetch failed: ${err instanceof Error ? err.message : String(err)}`);
  process.exit(3);
}

#!/usr/bin/env node
// Standalone Discord heartbeat poster — invoked by the CCR agent-runner
// session when discord-heartbeat fires. Deterministic by construction:
// same inputs → identical webhook payload, no LLM in this path.
//
// Why a script and not LLM-built JSON: a heartbeat's value is "the
// dispatch chain is alive" — that signal is meaningful only if every
// fire produces structurally identical output. Letting an LLM re-build
// the embed every fire wastes tokens and introduces drift (off-by-one
// hex color, missed field, etc.). The LLM in the CCR session does one
// thing: `execSync('node post.mjs')`, then surfaces the exit code.
//
// The embed shape mirrors workforce/skills/discord-ping/handler.ts so
// the two heartbeat paths look identical in Discord. When the trial
// validates and discord-heartbeat retires discord-ping, this script
// becomes the canonical implementation (the handler.ts can `import`
// from here in a future cleanup PR).
//
// Usage:
//   DISCORD_WEBHOOK_URL=<url> AGENT_SLUG=<slug> [TICKED_AT=<iso>] \
//     node workforce/skills/discord-heartbeat/post.mjs
//
// Exit codes:
//   0   — Discord returned 204 (success)
//   1   — env var missing / malformed
//   2   — non-2xx response from Discord
//   3   — network / fetch error
//
// Stdout: a single human-readable line (the same line format that
// discord-ping writes to S3 for audit). Stderr: error detail.

const COLOR_ALIVE = 0x3498db; // info blue — matches workforce/skills/discord-ping/handler.ts

const webhookUrl = process.env.DISCORD_WEBHOOK_URL;
const agentSlug = process.env.AGENT_SLUG;
const tickedAt = process.env.TICKED_AT ?? new Date().toISOString();

if (!webhookUrl) {
  console.error("post.mjs: DISCORD_WEBHOOK_URL env var is required");
  process.exit(1);
}
if (!agentSlug) {
  console.error("post.mjs: AGENT_SLUG env var is required");
  process.exit(1);
}
if (!/^https:\/\/discord\.com\/api\/webhooks\//.test(webhookUrl)) {
  console.error(`post.mjs: DISCORD_WEBHOOK_URL does not look like a Discord webhook URL (got "${webhookUrl.slice(0, 60)}...")`);
  process.exit(1);
}

// Strip sub-second precision — matches discord-ping/handler.ts "second
// precision" rule for the embed timestamp and the audit line.
const isoSecond = tickedAt.replace(/\.\d+Z$/, "Z");
const line = `[wf-pulse] ${agentSlug} alive at ${isoSecond}`;

const payload = {
  embeds: [
    {
      title: `wf-pulse · ${agentSlug}`,
      color: COLOR_ALIVE,
      timestamp: isoSecond,
    },
  ],
};

try {
  const res = await fetch(webhookUrl, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(payload),
  });
  if (res.status < 200 || res.status >= 300) {
    const text = await res.text().catch(() => "");
    console.error(`post.mjs: Discord webhook returned HTTP ${res.status}: ${text.slice(0, 256)}`);
    process.exit(2);
  }
  console.log(line);
  process.exit(0);
} catch (err) {
  console.error(`post.mjs: fetch failed: ${err instanceof Error ? err.message : String(err)}`);
  process.exit(3);
}

// Integration tests for the feed-post handler — Epic-011 Story 1 (#128).
//
// Locks the W-4 / W-1 contracts exercised by `runFeedPost`:
//   - skip-path: handler-output `__SKIP_NO_MATERIAL__` → RUN status=skipped,
//     skip_reason="no_material"; NO POST row.
//   - strict-equality: a response containing the sentinel inside a larger
//     body throws with `error_message="sentinel_in_body"` (Dario A2 /
//     #128 AC inversion guard).
//   - length-throw: `complete()` throws on `finish_reason==='length'` /
//     `stop_reason==='max_tokens'`; handler writes a RUN throw row and
//     propagates (R-9, W-4).
//   - LLM-artefact regex: body starting with "As an AI assistant..."
//     throws with an `llm_artefact_in_head:...` error_message (W-1).
//
// Plus a few structural tests on parseBodyAndTail() since it owns the
// structured-output protocol (kind + references[]) and a malformed tail
// is also a W-4 throw.

// IMPORTANT — env-var ordering: the handler's transitive imports
// (shared/ddb.ts, shared/memory.ts, shared/deliverable.ts) throw at
// module load if TABLE_NAME / BUCKET_NAME are unset (W-4 fail-loud).
// Static `import` is hoisted above any code in the file body, so we use
// the dynamic-`await import` pattern already established by
// backfill-tasks/handler-tests.ts — set env, THEN import. The test
// injects mocked deps, so the env-var values are placeholders for the
// throw-guard only; nothing in the test path actually hits AWS.
process.env.TABLE_NAME = "wf-table-test";
process.env.BUCKET_NAME = "wf-bucket-test";
process.env.STAGE = "test";

import { describe, expect, it, vi } from "vitest";

const { parseBodyAndTail, runFeedPost } = await import("./handler.js");
type FeedPostInput = import("./handler.js").FeedPostInput;
type FeedPostDeps = import("./handler.js").FeedPostDeps;

function fakeInput(overrides: Partial<FeedPostInput> = {}): FeedPostInput {
  return {
